#include <vector>

class Solution {
public:
    int countValidBinaryStrings(int n, int maxCost) {
        long long MOD = 1000000007;
        if (n <= 0) return 1;
        std::vector<std::vector<long long>> dp(maxCost + 1, std::vector<long long>(2, 0));
        dp[0][0] = 1;
        dp[0][1] = 1;
        for (int step = 1; step < n; ++step) {
            std::vector<std::vector<long long>> nxt(maxCost + 1, std::vector<long long>(2, 0));
            for (int c = 0; c <= maxCost; ++c) {
                // from 0
                if (c + 1 <= maxCost) nxt[c + 1][0] = (nxt[c + 1][0] + dp[c][0]) % MOD;
                nxt[c][1] = (nxt[c][1] + dp[c][0]) % MOD;
                // from 1
                nxt[c][0] = (nxt[c][0] + dp[c][1]) % MOD;
                if (c + 1 <= maxCost) nxt[c + 1][1] = (nxt[c + 1][1] + dp[c][1]) % MOD;
            }
            dp = std::move(nxt);
        }
        long long total = 0;
        for (int c = 0; c <= maxCost; ++c) {
            total = (total + dp[c][0] + dp[c][1]) % MOD;
        }
        return total;
    }
};

class Solution {
    public int countValidBinaryStrings(int n, int maxCost) {
        long MOD = 1_000_000_007L;
        if (n <= 0) return 1;
        long[][] dp = new long[maxCost + 1][2];
        dp[0][0] = 1;
        dp[0][1] = 1;
        for (int step = 1; step < n; step++) {
            long[][] nxt = new long[maxCost + 1][2];
            for (int c = 0; c <= maxCost; c++) {
                if (c + 1 <= maxCost) nxt[c + 1][0] = (nxt[c + 1][0] + dp[c][0]) % MOD;
                nxt[c][1] = (nxt[c][1] + dp[c][0]) % MOD;
                nxt[c][0] = (nxt[c][0] + dp[c][1]) % MOD;
                if (c + 1 <= maxCost) nxt[c + 1][1] = (nxt[c + 1][1] + dp[c][1]) % MOD;
            }
            dp = nxt;
        }
        long total = 0;
        for (int c = 0; c <= maxCost; c++) {
            total = (total + dp[c][0] + dp[c][1]) % MOD;
        }
        return (int) total;
    }
}

